-- =====================================================================
--  PrepConcurso AO — MININT: reforço de tópicos (SIC, organização do MININT,
--  organização político-administrativa, noções de Administração Pública,
--  História e Patriotismo). Gerado por tools/questoes_minint2.py.
--  Não duplica enunciados já existentes. Pode ser executado mais do que uma vez.
-- =====================================================================
with cat as (select id from public.categorias where nome = 'Ministério do Interior (MININT) — Prova Escrita'),
novas(area, enunciado, opcoes, correta) as (values
  ('Serviço de Investigação Criminal (SIC)', 'O Serviço de Investigação Criminal (SIC) foi oficializado em:', '["2002", "2015", "1975", "2010"]'::jsonb, 1),
  ('Serviço de Investigação Criminal (SIC)', 'O SIC resultou da fusão de quais organismos?', '["Polícia de Trânsito e Polícia Fiscal", "Direcção Nacional de Investigação Criminal (DNIC) e Polícia Económica", "Polícia de Intervenção Rápida e Bombeiros", "SME e Serviço Penitenciário"]'::jsonb, 1),
  ('Serviço de Investigação Criminal (SIC)', 'Com a sua criação, o SIC deixou de depender do Comando-Geral da Polícia Nacional e passou a depender directamente:', '["Do Tribunal Supremo", "Da Assembleia Nacional", "Do Ministério da Justiça", "Do Ministério do Interior"]'::jsonb, 3),
  ('Serviço de Investigação Criminal (SIC)', 'O primeiro Director-Geral do SIC, empossado em 2015, foi:', '["Manuel Homem", "Eugénio Pedro Alexandre", "Eugénio Laborinho", "Ângelo da Veiga Tavares"]'::jsonb, 1),
  ('Serviço de Investigação Criminal (SIC)', 'A missão principal do SIC é:', '["O combate a incêndios", "A prevenção, investigação e combate à criminalidade", "A emissão de passaportes e vistos", "A custódia de reclusos"]'::jsonb, 1),
  ('Serviço de Investigação Criminal (SIC)', 'Qual destes crimes está entre as prioridades de investigação do SIC?', '["Falta de uso do cinto de segurança", "Estacionamento em local proibido", "Atraso no pagamento da renda", "Branqueamento de capitais"]'::jsonb, 3),
  ('Serviço de Investigação Criminal (SIC)', 'O tráfico de seres humanos e de órgãos é um crime cuja investigação compete principalmente ao:', '["Serviço de Protecção Civil e Bombeiros", "SIC", "Serviço Penitenciário", "Ministério da Cultura"]'::jsonb, 1),
  ('Serviço de Investigação Criminal (SIC)', 'Na fase de instrução preparatória do processo penal, os órgãos de polícia criminal, como o SIC, actuam sob a direcção:', '["Do advogado do arguido", "Do Ministério Público", "Do Governador Provincial", "Do Administrador Municipal"]'::jsonb, 1),
  ('Serviço de Investigação Criminal (SIC)', 'O SIC é classificado como:', '["Órgão de polícia criminal", "Órgão de soberania", "Autarquia local", "Tribunal"]'::jsonb, 0),
  ('Serviço de Investigação Criminal (SIC)', 'Ao chegar ao local de um crime, o primeiro cuidado do agente de investigação deve ser:', '["Recolher objectos sem registar", "Limpar o local para facilitar a passagem", "Permitir a entrada de curiosos", "Isolar e preservar o local, sem mexer nos vestígios"]'::jsonb, 3),
  ('Serviço de Investigação Criminal (SIC)', 'A «cadeia de custódia» da prova consiste em:', '["Guardar as provas em casa do agente", "Prender o suspeito numa cela", "Destruir as provas depois do julgamento", "Documentar e garantir a integridade dos vestígios desde a recolha até ao tribunal"]'::jsonb, 3),
  ('Serviço de Investigação Criminal (SIC)', 'O agente do SIC que divulga nas redes sociais informações de um processo em investigação viola:', '["O dever de assiduidade", "O direito de reunião", "A liberdade religiosa", "O segredo de justiça"]'::jsonb, 3),
  ('Serviço de Investigação Criminal (SIC)', 'Considera-se em flagrante delito quem:', '["Mora perto do local do crime", "Tem antecedentes criminais", "Foi denunciado há um ano", "Está a cometer o crime ou acabou de o cometer"]'::jsonb, 3),
  ('Serviço de Investigação Criminal (SIC)', 'Segundo a lei angolana, o detido deve ser apresentado à autoridade judiciária competente no prazo máximo de:', '["7 dias", "6 meses", "30 dias", "48 horas"]'::jsonb, 3),
  ('Serviço de Investigação Criminal (SIC)', 'A investigação de crimes económico-financeiros, antes a cargo da Polícia Económica, passou a ser feita pelo:', '["Serviço Penitenciário", "Ministério das Finanças", "SIC", "SME"]'::jsonb, 2),
  ('Ministério do Interior', 'Desde Novembro de 2024, o Ministro do Interior de Angola é:', '["Eugénio Laborinho", "Manuel Homem", "Sebastião Martins", "Ângelo da Veiga Tavares"]'::jsonb, 1),
  ('Ministério do Interior', 'Antes de assumir o Ministério do Interior, Manuel Homem era:', '["Director do SIC", "Presidente da Assembleia Nacional", "Comandante-Geral da Polícia Nacional", "Governador da Província de Luanda"]'::jsonb, 3),
  ('Ministério do Interior', 'Manuel Homem substituiu no cargo de Ministro do Interior:', '["Eugénio Laborinho", "Ângelo da Veiga Tavares", "João Lourenço", "Fernando Garcia Miala"]'::jsonb, 0),
