  ('Ministério do Interior', 'A emissão de passaportes ordinários e a concessão de vistos competem ao:', '["SIC", "Ministério da Saúde", "Serviço de Migração e Estrangeiros (SME)", "Serviço Penitenciário"]'::jsonb, 2),
  ('Ministério do Interior', 'A emissão do Bilhete de Identidade de cidadão nacional é da responsabilidade:', '["Do Ministério do Turismo", "Do Serviço Penitenciário", "Do Ministério da Justiça e dos Direitos Humanos", "Do Serviço de Protecção Civil e Bombeiros"]'::jsonb, 2),
  ('Ministério do Interior', 'Segundo a Constituição, a Polícia Nacional é uma instituição:', '["Permanente, regular e apartidária, organizada com base na hierarquia e na disciplina", "Dependente dos governos provinciais", "Temporária e partidária", "Privada e lucrativa"]'::jsonb, 0),
  ('Ministério do Interior', 'O mais alto cargo de comando da Polícia Nacional de Angola é o de:', '["Chefe do Estado-Maior General", "Ministro do Interior", "Director-Geral do SIC", "Comandante-Geral"]'::jsonb, 3),
  ('Ministério do Interior', 'O efectivo do MININT, perante uma ordem manifestamente ilegal que implique a prática de um crime, deve:', '["Divulgá-la nas redes sociais", "Cumpri-la sem questionar", "Recusar o seu cumprimento", "Abandonar o serviço"]'::jsonb, 2),
  ('Ministério do Interior', 'A relação entre um agente e o seu comandante assenta principalmente no princípio:', '["Da eleição dos chefes", "Da hierarquia e disciplina", "Da livre negociação", "Da igualdade de comando"]'::jsonb, 1),
  ('Ministério do Interior', 'A gestão das cadeias e a execução das penas de prisão competem ao:', '["SIC", "SME", "Serviço Penitenciário", "Tribunal Constitucional"]'::jsonb, 2),
  ('Organização Política e Administrativa', 'Com a Lei da Divisão Político-Administrativa (Lei n.º 14/24), Angola passou a ter:', '["25 províncias, 250 municípios e 350 comunas", "20 províncias, 300 municípios e 400 comunas", "21 províncias, 326 municípios e 378 comunas", "18 províncias, 164 municípios e 518 comunas"]'::jsonb, 2),
  ('Organização Política e Administrativa', 'Antes da nova divisão político-administrativa de 2024, Angola tinha:', '["15 províncias", "21 províncias", "18 províncias", "25 províncias"]'::jsonb, 2),
  ('Organização Política e Administrativa', 'A província de Icolo e Bengo foi criada a partir da divisão da província de:', '["Malanje", "Luanda", "Bengo", "Cuanza Norte"]'::jsonb, 1),
  ('Organização Política e Administrativa', 'As províncias do Cuando e do Cubango resultaram da divisão da antiga província de:', '["Huíla", "Cunene", "Cuando Cubango", "Moxico"]'::jsonb, 2),
  ('Organização Política e Administrativa', 'Segundo a Constituição, o titular do Poder Executivo é:', '["O Presidente da Assembleia Nacional", "O Tribunal Constitucional", "O Presidente da República", "O Ministro de Estado e Chefe da Casa Civil"]'::jsonb, 2),
  ('Organização Política e Administrativa', 'Os Ministros de Estado e os Ministros são, segundo a Constituição:', '["Eleitos directamente pelos cidadãos", "Órgãos de soberania independentes", "Órgãos auxiliares do Presidente da República", "Juízes do Tribunal Supremo"]'::jsonb, 2),
  ('Organização Política e Administrativa', 'O mandato do Presidente da República e dos Deputados à Assembleia Nacional é de:', '["6 anos", "7 anos", "4 anos", "5 anos"]'::jsonb, 3),
  ('Organização Política e Administrativa', 'Apreciar a constitucionalidade das leis compete ao:', '["Ministério do Interior", "Governo Provincial", "Tribunal de Contas", "Tribunal Constitucional"]'::jsonb, 3),
  ('Organização Política e Administrativa', 'O órgão público independente que defende os direitos dos cidadãos perante a Administração Pública é o:', '["Governador do BNA", "Provedor de Justiça", "Director do SIC", "Comandante-Geral da Polícia"]'::jsonb, 1),
  ('Organização Política e Administrativa', 'Exercer a acção penal e defender a legalidade democrática compete, em especial, à:', '["Polícia Nacional", "Assembleia Nacional", "Administração Municipal", "Procuradoria-Geral da República"]'::jsonb, 3),
  ('Organização Política e Administrativa', 'O Orçamento Geral do Estado (OGE) é aprovado:', '["Pela Assembleia Nacional, sob proposta do Executivo", "Pelo Tribunal Supremo", "Pelos Governadores Provinciais", "Pelo Banco Nacional de Angola sem intervenção do Parlamento"]'::jsonb, 0),
  ('Organização Política e Administrativa', 'Na estrutura da administração local do Estado, o município é dirigido por um:', '["Ministro", "Governador Provincial", "Administrador Municipal", "Juiz de Direito"]'::jsonb, 2),
  ('Noções Gerais de Administração Pública', 'A finalidade da Administração Pública é:', '["A promoção de partidos políticos", "A defesa dos interesses dos funcionários", "A prossecução do interesse público, no respeito pelos direitos dos cidadãos", "O lucro do Estado"]'::jsonb, 2),
  ('Noções Gerais de Administração Pública', 'Segundo o princípio da legalidade, a Administração Pública:', '["Só obedece ao chefe directo", "Está acima da lei", "Só pode agir com base na lei e dentro dos limites da lei", "Pode fazer tudo o que a lei não proíbe"]'::jsonb, 2),
  ('Noções Gerais de Administração Pública', 'O princípio da imparcialidade obriga a Administração a:', '["Tratar todos os interessados com isenção, sem favoritismos", "Favorecer familiares e amigos", "Não ouvir os cidadãos", "Decidir sempre a favor do Estado"]'::jsonb, 0),
  ('Noções Gerais de Administração Pública', 'O princípio da proporcionalidade exige que as decisões administrativas:', '["Beneficiem a maioria política", "Sejam tomadas por sorteio", "Sejam sempre as mais severas", "Sejam adequadas, necessárias e não excessivas face ao fim pretendido"]'::jsonb, 3),
  ('Noções Gerais de Administração Pública', 'O princípio da igualdade proíbe a Administração de:', '["Privilegiar ou prejudicar alguém em razão da raça, sexo, religião, origem ou opinião política", "Aplicar a lei", "Cobrar impostos", "Atender os cidadãos por ordem de chegada"]'::jsonb, 0),
  ('Noções Gerais de Administração Pública', 'A desconcentração administrativa consiste em:', '["Transferir poderes para entidades privadas", "Concentrar todas as decisões no Presidente", "Extinguir serviços públicos", "Distribuir competências por órgãos subordinados dentro da mesma pessoa colectiva"]'::jsonb, 3),
  ('Noções Gerais de Administração Pública', 'A descentralização administrativa consiste em:', '["Transferir atribuições do Estado para outras pessoas colectivas públicas, como as autarquias locais", "Privatizar empresas públicas", "Mudar a capital do país", "Distribuir funções entre secções do mesmo ministério"]'::jsonb, 0),
  ('Noções Gerais de Administração Pública', 'Os ministérios e os seus serviços centrais integram a:', '["Administração directa do Estado", "Actividade privada", "Administração autónoma", "Administração indirecta"]'::jsonb, 0),
  ('Noções Gerais de Administração Pública', 'Os institutos públicos, com personalidade jurídica própria, integram a:', '["Função legislativa", "Administração indirecta do Estado", "Administração directa do Estado", "Função jurisdicional"]'::jsonb, 1),
  ('Noções Gerais de Administração Pública', 'As autarquias locais integram a:', '["Administração militar", "Administração directa do Estado", "Administração autónoma", "Função jurisdicional"]'::jsonb, 2),
  ('Noções Gerais de Administração Pública', 'O acto administrativo é:', '["Uma lei aprovada pela Assembleia Nacional", "Uma sentença de um tribunal", "Um contrato entre particulares", "Uma decisão de um órgão da Administração que produz efeitos jurídicos num caso concreto"]'::jsonb, 3),
  ('Noções Gerais de Administração Pública', 'Quando o cidadão contesta uma decisão junto do próprio autor do acto, apresenta uma:', '["Reclamação", "Queixa-crime", "Recurso hierárquico", "Petição de habeas corpus"]'::jsonb, 0),
  ('Noções Gerais de Administração Pública', 'Quando o cidadão contesta uma decisão junto do superior hierárquico de quem a tomou, apresenta um:', '["Requerimento de férias", "Recurso de revista", "Recurso hierárquico", "Reclamação"]'::jsonb, 2),
  ('Noções Gerais de Administração Pública', 'Um serviço público orientado para o cidadão deve, acima de tudo:', '["Atender com cortesia, rapidez e transparência", "Esconder informação", "Exigir gratificações para acelerar processos", "Atender primeiro os conhecidos"]'::jsonb, 0),
  ('História de Angola', 'O dia 4 de Fevereiro de 1961 assinala:', '["A assinatura dos Acordos de Alvor", "O início da luta armada de libertação nacional", "O fim da guerra civil", "A proclamação da independência"]'::jsonb, 1),
  ('História de Angola', 'O MPLA foi fundado, segundo a data oficial, em:', '["1956", "1975", "1961", "1966"]'::jsonb, 0),
  ('História de Angola', 'A UNITA foi fundada em:', '["1956", "1966", "1975", "1991"]'::jsonb, 1),
  ('História de Angola', 'A profetisa do Reino do Kongo que liderou o movimento antoniano e foi executada em 1706 foi:', '["Lueji", "Kimpa Vita (D. Beatriz)", "Deolinda Rodrigues", "Njinga Mbandi"]'::jsonb, 1),
  ('História de Angola', 'O nome «Angola» tem origem no título dos reis do Ndongo, que era:', '["Soba", "Mwata", "Ngola", "Mani"]'::jsonb, 2),
  ('História de Angola', 'A batalha de Mbwila (Ambuíla), em que o Reino do Kongo foi derrotado pelos portugueses, ocorreu em:', '["1885", "1961", "1665", "1482"]'::jsonb, 2),
  ('História de Angola', 'O dia 1 de Agosto celebra:', '["O Dia das Forças Armadas (criação das FAPLA, em 1974)", "O Dia da Independência", "O Dia do Herói Nacional", "O Dia da Paz"]'::jsonb, 0),
  ('História de Angola', 'Angola foi admitida como membro da Organização das Nações Unidas (ONU) em:', '["1961", "1992", "1975", "1976"]'::jsonb, 3),
  ('História de Angola', 'O Dia da Mulher Angolana celebra-se a:', '["2 de Março", "8 de Março", "4 de Abril", "11 de Novembro"]'::jsonb, 0),
  ('História de Angola', 'O dia 4 de Abril é feriado nacional dedicado à:', '["Independência Nacional", "Polícia Nacional", "Paz e Reconciliação Nacional", "Mulher Angolana"]'::jsonb, 2),
  ('Patriotismo e Símbolos Nacionais', 'Segundo a Constituição, a defesa da Pátria é:', '["Tarefa exclusiva dos militares estrangeiros", "Direito e dever fundamental de todos os angolanos", "Obrigação apenas dos políticos", "Opcional para os cidadãos"]'::jsonb, 1),
  ('Patriotismo e Símbolos Nacionais', 'Na Insígnia da República de Angola, o livro aberto simboliza:', '["A religião", "O comércio", "A educação e a cultura", "A Constituição apenas"]'::jsonb, 2),
  ('Patriotismo e Símbolos Nacionais', 'O hino nacional de Angola chama-se:', '["«Angola Avante»", "«Pátria Amada»", "«Angola Unida»", "«Hino da Liberdade»"]'::jsonb, 0),
  ('Patriotismo e Símbolos Nacionais', 'Qual destas atitudes revela patriotismo de um agente do MININT?', '["Faltar ao serviço sem justificação", "Aceitar «gasosas» para facilitar processos", "Usar a farda para benefício pessoal", "Servir o cidadão com honestidade e recusar a corrupção"]'::jsonb, 3),
  ('Patriotismo e Símbolos Nacionais', 'Participar nas eleições e cumprir as obrigações fiscais são exemplos de:', '["Actos de rebeldia", "Cidadania e patriotismo", "Deveres apenas dos funcionários públicos", "Actividades proibidas"]'::jsonb, 1),
  ('Patriotismo e Símbolos Nacionais', 'A unidade nacional significa:', '["A separação das províncias", "A superioridade de uma região sobre as outras", "A união de todos os angolanos, acima das diferenças de origem, língua, etnia ou religião", "A existência de um único partido"]'::jsonb, 2)
)
insert into public.questoes (tipo, area, categoria_id, enunciado, opcoes, correta)
select 'conhecimento', n.area, cat.id, n.enunciado, n.opcoes, n.correta
from novas n cross join cat
where not exists (select 1 from public.questoes x where x.categoria_id = cat.id and lower(x.enunciado) = lower(n.enunciado))
returning area;
